package com.game_manager.gm.report;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import java.sql.Timestamp; import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.http.MediaType; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.*; import tools.jackson.databind.ObjectMapper;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class ReportSecurityIntegrationTest {@Autowired MockMvc mvc;@Autowired JdbcTemplate db;@Autowired PasswordEncoder encoder;ObjectMapper json=new ObjectMapper();
 @Test void rejectsMissingPermissionAndHidesForeignReport()throws Exception{UUID customer=user("CUSTOMER"),first=user("EMPLOYEE"),second=user("EMPLOYEE");mvc.perform(get("/api/v1/reports").header("Authorization",bearer(login(customer)))).andExpect(status().isForbidden());MvcResult created=mvc.perform(post("/api/v1/reports").header("Authorization",bearer(login(first))).contentType(MediaType.APPLICATION_JSON).content("{\"definitionKey\":\"orders\",\"format\":\"CSV\",\"from\":\"2026-01-01T00:00:00Z\",\"to\":\"2026-02-01T00:00:00Z\",\"timezone\":\"Europe/Belgrade\",\"locale\":\"sr-RS\"}")).andExpect(status().isAccepted()).andReturn();String id=json.readTree(created.getResponse().getContentAsByteArray()).get("id").asText();mvc.perform(get("/api/v1/reports/{id}",id).header("Authorization",bearer(login(second)))).andExpect(status().isNotFound());}
 private UUID user(String role){UUID id=UUID.randomUUID();Instant now=Instant.now();db.update("INSERT INTO users(id,name,email,password_hash,role,active,created_at,updated_at,version) VALUES(?,?,?,?,?,?,?,?,0)",id.toString(),"Report User",id+"@example.com",encoder.encode("StrongPass1!"),role,true,Timestamp.from(now),Timestamp.from(now));return id;}private String login(UUID id)throws Exception{String email=db.queryForObject("SELECT email FROM users WHERE id=?",String.class,id.toString());MvcResult result=mvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"StrongPass1!\"}")).andExpect(status().isOk()).andReturn();return json.readTree(result.getResponse().getContentAsByteArray()).get("token").asText();}private static String bearer(String token){return "Bearer "+token;}}
